                 1.011919863000000e-09 * T2 - 1.169438824000000e-13 * T3;
    // species 3: C
    species[3] = -3.215377200000000e-04 + 1.467584460000000e-06 * T -
                 2.196704610000000e-09 * T2 + 1.066085760000000e-12 * T3;
